INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.78.0',
  '2026-08-07',
  'Converter: криптовалюты, выбор из справочника и график за месяц',
  E'Валюту больше не надо угадывать по коду: кнопка ➕ открывает справочник источника — 338 позиций, 154 обычные валюты и 184 криптовалюты. Есть поиск по коду и названию и переключатель «Все / Обычные / Крипто». Ввод кода руками остался на случай, если справочник недоступен.\n\nКриптовалюты считаются наравне с обычными, в обе стороны: биткоин к драму, эфир к евро — как угодно.\n\nПоявился график курса за месяц. Он не показывается сразу: кнопка «График за месяц» разворачивает столбик графиков — по одному на каждую добавленную валюту, с изменением в процентах за период. Первое построение чуть дольше: сервер догружает недостающие дни из источника, дальше они берутся из своей базы.',
  E'Новая таблица currency_history. Всё хранится ОТНОСИТЕЛЬНО ДОЛЛАРА (сколько единиц валюты за 1 USD): любая пара получается делением, и не нужно держать матрицу «каждая к каждой». День — DATE, а не момент времени: источник отдаёт дневные срезы.\n\nИсточник (@fawazahmed0/currency-api) держит датированные срезы, поэтому недостающие дни докачиваются по требованию, а не копятся месяц, прежде чем показать первый график. Ошибки докачки намеренно молчаливые: пропуск дня — дырка в графике, а не повод отдать пустой экран. Потолок периода 92 дня: каждый недостающий день это отдельный запрос к источнику.\n\nДень считается собранным, только если в нём есть ВСЕ запрошенные валюты: иначе на графике одной была бы дырка, а у соседней в тот же день — точка.\n\nСправочник источника не помечает, где крипто: список ISO 4217 зашит, всё остальное показывается как криптовалюта. Ошибка здесь безобидна — это лишь группировка в выборе.\n\nГрафик — свой компонент, а не общий Sparkline: тот считает ось от нуля, и курс, весь месяц державшийся около 385, выглядел бы прямой линией у верхнего края. Здесь масштаб от минимума до максимума с запасом в 10%.\n\nПри смене базовой валюты ряды сбрасываются: они построены к прежней базе и показали бы не тот курс.'
);
-- +goose StatementEnd

